/*
 * GPS NEO-6M/8M Tracker — ESP32
 *
 * Hardware:
 *   NEO-6M/8M GPS Module:
 *     VCC -> 3.3V
 *     GND -> GND
 *     TX  -> GPIO16 (RX2)
 *     RX  -> GPIO17 (TX2)
 *   LED:
 *     Anode -> D2 (via 220 ohm resistor)
 *     Cathode -> GND
 *
 * The GPS module sends NMEA sentences at 9600 baud.
 * ESP32 Serial2 reads the data and TinyGPS++ parses it.
 * LED on D2 blinks when a valid GPS fix is obtained.
 */

#include <TinyGPS++.h>

// TinyGPS++ instance
TinyGPSPlus gps;

// LED pin for GPS fix indication
const int LED_PIN = 2;
bool ledState = false;
unsigned long lastBlink = 0;

void setup() {
  Serial.begin(115200);
  Serial2.begin(9600, SERIAL_8N1, 16, 17);

  pinMode(LED_PIN, OUTPUT);
  digitalWrite(LED_PIN, LOW);

  Serial.println("========================================");
  Serial.println("  GPS NEO-6M/8M Tracker");
  Serial.println("  TinyGPS++ Library");
  Serial.println("========================================");
  Serial.println("Waiting for GPS fix...");
  Serial.println();
}

void loop() {
  // Feed NMEA data from GPS module into TinyGPS++
  while (Serial2.available() > 0) {
    gps.encode(Serial2.read());
  }

  // Print GPS data every second
  static unsigned long lastPrint = 0;
  if (millis() - lastPrint >= 1000) {
    lastPrint = millis();

    if (gps.location.isValid()) {
      // Valid fix — blink LED
      if (millis() - lastBlink >= 500) {
        lastBlink = millis();
        ledState = !ledState;
        digitalWrite(LED_PIN, ledState ? HIGH : LOW);
      }

      Serial.println("--- GPS Fix Acquired ---");

      // Location
      Serial.print("Latitude:    ");
      Serial.print(gps.location.lat(), 6);
      Serial.println(" deg");
      Serial.print("Longitude:   ");
      Serial.print(gps.location.lng(), 6);
      Serial.println(" deg");

      // Altitude
      if (gps.altitude.isValid()) {
        Serial.print("Altitude:    ");
        Serial.print(gps.altitude.meters(), 1);
        Serial.print(" m  (");
        Serial.print(gps.altitude.feet(), 1);
        Serial.println(" ft)");
      }

      // Satellites & HDOP
      if (gps.satellites.isValid()) {
        Serial.print("Satellites:  ");
        Serial.println(gps.satellites.value());
      }
      if (gps.hdop.isValid()) {
        Serial.print("HDOP:        ");
        Serial.println(gps.hdop.hdop(), 1);
      }

      // Speed
      if (gps.speed.isValid()) {
        Serial.print("Speed:       ");
        Serial.print(gps.speed.kmph(), 1);
        Serial.print(" km/h  (");
        Serial.print(gps.speed.mph(), 1);
        Serial.print(" mph  ");
        Serial.print(gps.speed.knots(), 1);
        Serial.println(" knots)");
      }

      // Course
      if (gps.course.isValid()) {
        Serial.print("Course:      ");
        Serial.print(gps.course.deg(), 1);
        Serial.println(" deg");
      }

      // Date
      if (gps.date.isValid()) {
        Serial.print("Date:        ");
        Serial.print(gps.date.day());
        Serial.print("/");
        Serial.print(gps.date.month());
        Serial.print("/");
        Serial.println(gps.date.year());
      }

      // Time
      if (gps.time.isValid()) {
        Serial.print("Time (UTC):  ");
        if (gps.time.hour() < 10) Serial.print('0');
        Serial.print(gps.time.hour());
        Serial.print(':');
        if (gps.time.minute() < 10) Serial.print('0');
        Serial.print(gps.time.minute());
        Serial.print(':');
        if (gps.time.second() < 10) Serial.print('0');
        Serial.println(gps.time.second());
      }

      // Stats
      Serial.print("Chars:       ");
      Serial.print(gps.charsProcessed());
      Serial.print("  Pass: ");
      Serial.print(gps.passedChecksum());
      Serial.print("  Fail: ");
      Serial.println(gps.failedChecksum());
      Serial.println();

    } else {
      // No fix yet
      Serial.print(".");
      digitalWrite(LED_PIN, LOW);
    }
  }
}
